function fmtUp(s){if(s<60)return s+'s';if(s<3600)return Math.floor(s/60)+'m '+String(s%60).padStart(2,'0')+'s';return Math.floor(s/3600)+'h '+Math.floor((s%3600)/60)+'m';}
function fmtBytes(n){n=Number(n)||0;if(n>=1048576)return(n/1048576).toFixed(n>=10485760?1:2)+' MB';if(n>=1024)return(n/1024).toFixed(n>=10240?0:1)+' KB';return n+' B';}
function pct(used,total){total=Number(total)||0;used=Number(used)||0;return total>0?Math.max(0,Math.min(100,used*100/total)):0;}
